export function directionFor(dx,dy,deadzone=12){if(Math.hypot(dx,dy)<deadzone)return null;return Math.abs(dx)>Math.abs(dy)?dx>0?3:2:dy>0?1:0;}
// toLocal maps a screen-space offset into the pad's own (possibly rotated) space; the identity by default.
export function bindJoystick(pad,knob,onDirection,toLocal=(dx,dy)=>[dx,dy]){let pointer=null;const reset=()=>{pointer=null;knob.style.transform='translate(0,0)';onDirection(null);};const update=e=>{const r=pad.getBoundingClientRect(),[dx,dy]=toLocal(e.clientX-r.left-r.width/2,e.clientY-r.top-r.height/2),length=Math.hypot(dx,dy),scale=length>34?34/length:1;knob.style.transform=`translate(${dx*scale}px,${dy*scale}px)`;onDirection(directionFor(dx,dy));};pad.addEventListener('pointerdown',e=>{if(pointer!==null)return;pointer=e.pointerId;pad.setPointerCapture(pointer);e.preventDefault();update(e);});pad.addEventListener('pointermove',e=>{if(e.pointerId===pointer){e.preventDefault();update(e);}});for(const type of ['pointerup','pointercancel','lostpointercapture'])pad.addEventListener(type,e=>{if(e.pointerId===pointer)reset();});window.addEventListener('blur',reset);document.addEventListener('visibilitychange',()=>{if(document.hidden)reset();});return reset;}
